package net.goui.cosmicdungeon.playerclass.dragoon.repair;

import net.goui.cosmicdungeon.economy.CurrencyDenomination;
import net.goui.cosmicdungeon.economy.CurrencyService;
import net.goui.cosmicdungeon.network.DragoonRepairPayloads;
import net.goui.cosmicdungeon.network.ModNetwork;
import net.goui.cosmicdungeon.playerclass.api.ClassData;
import net.goui.cosmicdungeon.playerclass.api.ClassKeys;
import net.goui.cosmicdungeon.trade.TradeSessionData;
import net.minecraft.ChatFormatting;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.network.chat.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.SimpleContainer;
import net.minecraft.world.SimpleMenuProvider;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.neoforged.neoforge.server.ServerLifecycleHooks;

import java.util.*;

public final class DragoonRepairSessionData {
    private static final long INVITE_EXPIRATION_TICKS = 600L; private static final double RANGE_SQR = 64.0D;
    private static final Map<InviteKey, PendingInvite> invites = new HashMap<>(); private static final Map<UUID, RepairSession> sessions = new HashMap<>();
    private DragoonRepairSessionData() {}
    public static void invite(ServerPlayer dragoon, ServerPlayer target) { cleanupExpiredInvites(dragoon.level().getServer()); if (!isDragoon(dragoon)) { dragoon.sendSystemMessage(Component.literal("Only Dragoons can start Repair Affinity.")); return; } if (target==null || dragoon.getUUID().equals(target.getUUID())) { dragoon.sendSystemMessage(Component.literal("Choose another online player to repair for.")); return; } if (!playersReady(dragoon,target)) { dragoon.sendSystemMessage(Component.literal("Both players must be alive, nearby, and in the same dimension.")); return; } if (isBusy(dragoon) || isBusy(target) || TradeSessionData.isBusy(dragoon) || TradeSessionData.isBusy(target)) { dragoon.sendSystemMessage(Component.literal("One of you is already busy.")); return; } long now=dragoon.level().getGameTime(); invites.put(new InviteKey(dragoon.getUUID(), target.getUUID()), new PendingInvite(dragoon.getUUID(), target.getUUID(), now)); target.sendSystemMessage(inviteMessage(dragoon.getName().getString())); dragoon.sendSystemMessage(Component.literal("Repair invite sent to "+target.getName().getString()+".")); }
    public static boolean acceptInvite(ServerPlayer target, ServerPlayer dragoon) { cleanupExpiredInvites(target.level().getServer()); if (dragoon==null) { target.sendSystemMessage(Component.literal("That Dragoon is no longer online.")); return false; } InviteKey key=new InviteKey(dragoon.getUUID(), target.getUUID()); PendingInvite inv=invites.remove(key); if (inv==null) { target.sendSystemMessage(Component.literal("No pending repair invite from "+dragoon.getName().getString()+".")); return false; } if (inv.isExpired(target.level().getGameTime())) { target.sendSystemMessage(Component.literal("That repair invite expired.")); return false; } if (!isDragoon(dragoon) || !playersReady(dragoon,target) || isBusy(dragoon) || isBusy(target) || TradeSessionData.isBusy(dragoon) || TradeSessionData.isBusy(target)) { target.sendSystemMessage(Component.literal("Unable to start Repair Affinity right now.")); return false; } removePendingInvitesInvolving(dragoon.getUUID()); removePendingInvitesInvolving(target.getUUID()); RepairSession s=new RepairSession(dragoon,target); sessions.put(dragoon.getUUID(),s); sessions.put(target.getUUID(),s); if (!s.open()) { s.cancel("Unable to open Repair Affinity"); return false; } return true; }
    public static boolean denyInvite(ServerPlayer target, ServerPlayer dragoon) { if (dragoon==null) return false; boolean ok=invites.remove(new InviteKey(dragoon.getUUID(), target.getUUID()))!=null; target.sendSystemMessage(Component.literal(ok?"Denied repair request.":"No pending repair request.")); if (ok) dragoon.sendSystemMessage(Component.literal(target.getName().getString()+" denied your repair request.")); return ok; }
    public static RepairSession get(ServerPlayer p) { return p==null?null:sessions.get(p.getUUID()); } public static boolean isBusy(ServerPlayer p) { return p!=null && sessions.containsKey(p.getUUID()); }
    public static void cancel(ServerPlayer p,String reason){ RepairSession s=get(p); if(s!=null)s.cancel(reason); else if(p!=null)p.sendSystemMessage(Component.literal("No active repair session to cancel.")); }
    public static void handleLogout(ServerPlayer p){ if(p==null)return; removePendingInvitesInvolving(p.getUUID()); RepairSession s=get(p); if(s!=null)s.cancelBecausePlayerLeft(p); }
    public static void cleanupExpiredInvites(MinecraftServer server){ if(server==null)return; long now=server.overworld().getGameTime(); invites.entrySet().removeIf(e->e.getValue().isExpired(now)); }
    public static void tick(MinecraftServer server){ cleanupExpiredInvites(server); Set<RepairSession> unique = new HashSet<>(sessions.values()); for (RepairSession s: unique) s.checkBreakConditions(); }
    private static boolean isDragoon(ServerPlayer p){ return p!=null && ClassKeys.CLASS_ID_DRAGOON.equals(ClassData.getClassId(p)); }
    private static boolean playersReady(ServerPlayer a, ServerPlayer b){ return a!=null&&b!=null&&a.isAlive()&&b.isAlive()&&!a.isSpectator()&&!b.isSpectator()&&a.level().dimension().equals(b.level().dimension())&&a.distanceToSqr(b)<=RANGE_SQR; }
    private static void removePendingInvitesInvolving(UUID id){ invites.entrySet().removeIf(e->e.getValue().involves(id)); }
    private static Component inviteMessage(String name){ return Component.literal(name+" offers Repair Affinity. ").append(Component.literal("[Accept Repair]").withStyle(Style.EMPTY.withColor(ChatFormatting.GREEN).withClickEvent(new ClickEvent.RunCommand("/repair accept "+name)).withHoverEvent(new HoverEvent.ShowText(Component.literal("Accept repair request"))))).append(" ").append(Component.literal("[Deny Repair]").withStyle(Style.EMPTY.withColor(ChatFormatting.RED).withClickEvent(new ClickEvent.RunCommand("/repair deny "+name)))); }
    private record InviteKey(UUID dragoon, UUID target){} private record PendingInvite(UUID dragoon, UUID target, long created){ boolean isExpired(long now){return now-created>=INVITE_EXPIRATION_TICKS;} boolean involves(UUID id){return dragoon.equals(id)||target.equals(id);} }

    public static final class RepairSession {
        private final UUID sessionId=UUID.randomUUID(), dragoon, target; private final SimpleContainer repairContainer=new SimpleContainer(1); private boolean ended, finalizing, targetReady; private int selectedUnits=1; private long feeTrace;
        RepairSession(ServerPlayer d, ServerPlayer t){ dragoon=d.getUUID(); target=t.getUUID(); }
        public SimpleContainer repairContainer(){ return repairContainer; } public boolean isValidFor(Player p){ return p!=null&&!ended&&(p.getUUID().equals(dragoon)||p.getUUID().equals(target)); } public boolean canEditRepairSlot(Player p){ return isTarget(p)&&!targetReady&&!finalizing&&!ended; } private boolean isTarget(Player p){return p!=null&&p.getUUID().equals(target);} private boolean isDragoonPlayer(Player p){return p!=null&&p.getUUID().equals(dragoon);} public boolean canCancelFromMenuClose(ServerPlayer p){ return !ended&&!finalizing&&isValidFor(p); }
        public boolean open(){ MinecraftServer srv=server(); if(srv==null)return false; ServerPlayer d=srv.getPlayerList().getPlayer(dragoon), t=srv.getPlayerList().getPlayer(target); if(d==null||t==null)return false; d.openMenu(new SimpleMenuProvider((id,inv,pl)->new DragoonRepairMenu(id,inv,this), Component.literal("Repair Affinity: "+t.getName().getString()))); t.openMenu(new SimpleMenuProvider((id,inv,pl)->new DragoonRepairMenu(id,inv,this), Component.literal("Repair Affinity: "+d.getName().getString()))); syncAll("Place a supported damaged item."); return true; }
        public void onRepairItemChanged(Player p){ if(ended||finalizing)return; targetReady=false; ItemStack st=repairContainer.getItem(0); selectedUnits = DragoonRepairRules.isSupportedDamagedItem(st) ? DragoonRepairRules.requiredUnitsToFull(st) : 1; syncAll(DragoonRepairRules.isValidRepairItemShape(st)&&!DragoonRepairRules.isSupportedDamagedItem(st)?"Elias has not taught this repair yet.":""); }
        public void adjustFee(ServerPlayer p,String denom,int delta){ if(!isTarget(p)||targetReady||finalizing)return; CurrencyDenomination d=CurrencyDenomination.fromId(denom); if(d==null)return; feeTrace=Math.max(0, Math.min(CurrencyService.getBalanceTrace(p), feeTrace + d.traceValue()*delta)); targetReady=false; syncAll(""); }
        public void selectUnits(ServerPlayer p,int units){ if(!isTarget(p)||targetReady||finalizing)return; ItemStack st=repairContainer.getItem(0); if(!DragoonRepairRules.isSupportedDamagedItem(st))return; selectedUnits=DragoonRepairRules.clampUnits(st,units); targetReady=false; syncAll(""); }
        public void setReady(ServerPlayer p,boolean ready){ if(!isTarget(p)||finalizing)return; if(ready && validate(false)!=null) { syncAll(validate(false)); return; } targetReady=ready; syncAll(""); }
        public void repair(ServerPlayer p){ if(!isDragoonPlayer(p)||!targetReady||finalizing||ended)return; String fail=validate(true); if(fail!=null){ syncAll(fail); return; } finalizing=true; syncAll("Repairing..."); MinecraftServer srv=server(); ServerPlayer d=srv.getPlayerList().getPlayer(dragoon), t=srv.getPlayerList().getPlayer(target); DragoonRepairTransactionService.Result r=DragoonRepairTransactionService.finalizeRepair(d,t,repairContainer,selectedUnits,feeTrace); if(r!=DragoonRepairTransactionService.Result.SUCCESS){ finalizing=false; syncAll("Repair failed: "+r.name().toLowerCase(Locale.ROOT).replace('_',' ')); return; } targetReady=false; finalizing=false; syncAll("Repair complete. Customer may take the item."); d.sendSystemMessage(Component.literal("Repair complete.")); t.sendSystemMessage(Component.literal("Repair complete.")); }
        private String validate(boolean requireMenu){ MinecraftServer srv=server(); if(srv==null)return"Server unavailable."; ServerPlayer d=srv.getPlayerList().getPlayer(dragoon), t=srv.getPlayerList().getPlayer(target); if(!playersReady(d,t))return"Both players must stay alive, nearby, and in the same dimension."; if(!isDragoon(d))return"Repair provider is no longer a Dragoon."; if(requireMenu && (!(d.containerMenu instanceof DragoonRepairMenu)||!(t.containerMenu instanceof DragoonRepairMenu)))return"Both players must keep Repair Affinity open."; ItemStack st=repairContainer.getItem(0); Optional<Item> mat=DragoonRepairRules.materialFor(st); if(mat.isEmpty())return"Elias has not taught this repair yet."; if(selectedUnits<1||selectedUnits>DragoonRepairRules.requiredUnitsToFull(st))return"Select a valid repair amount."; if(DragoonRepairTransactionService.count(d, mat.get())<selectedUnits)return"Dragoon lacks required materials."; if(CurrencyService.getBalanceTrace(t)<feeTrace)return"Customer lacks the offered labor fee."; if(feeTrace>CurrencyService.getCapacity(d)-CurrencyService.getBalanceTrace(d))return"Dragoon cannot receive that labor fee."; if(TradeSessionData.isBusy(d)||TradeSessionData.isBusy(t))return"One of you is already in a trade."; return null; }
        public void cancelFromMenuClose(ServerPlayer p){ cancel("menu closed"); } public void checkBreakConditions(){ if(ended)return; MinecraftServer srv=server(); if(srv==null)return; ServerPlayer d=srv.getPlayerList().getPlayer(dragoon), t=srv.getPlayerList().getPlayer(target); if(!playersReady(d,t)) cancel("repair conditions broke"); }
        public void cancelBecausePlayerLeft(ServerPlayer p){ cancel("player disconnected", p); }
        public void cancel(String reason){ cancel(reason, null); }
        private void cancel(String reason, ServerPlayer departingPlayer){ if(ended)return; MinecraftServer srv=server(); markEnded(); if(srv!=null){ ServerPlayer t=srv.getPlayerList().getPlayer(target), d=srv.getPlayerList().getPlayer(dragoon); if(t==null && departingPlayer!=null && departingPlayer.getUUID().equals(target)) t=departingPlayer; if(t!=null) { moveItemToTarget(t); t.closeContainer(); t.sendSystemMessage(Component.literal("Repair cancelled: "+reason)); } else repairContainer.clearContent(); if(d!=null){ d.closeContainer(); d.sendSystemMessage(Component.literal("Repair cancelled: "+reason)); }} else repairContainer.clearContent(); }
        private void moveItemToTarget(ServerPlayer t){ ItemStack s=repairContainer.removeItemNoUpdate(0); if(!s.isEmpty()) t.getInventory().placeItemBackInInventory(s); repairContainer.clearContent(); }
        private void syncAll(String msg){ MinecraftServer srv=server(); if(srv==null||ended)return; ServerPlayer d=srv.getPlayerList().getPlayer(dragoon), t=srv.getPlayerList().getPlayer(target); if(d!=null)syncTo(d,msg); if(t!=null)syncTo(t,msg); }
        private void syncTo(ServerPlayer viewer,String msg){ if(!(viewer.containerMenu instanceof DragoonRepairMenu))return; MinecraftServer srv=server(); ServerPlayer d=srv.getPlayerList().getPlayer(dragoon), t=srv.getPlayerList().getPlayer(target); ItemStack st=repairContainer.getItem(0); Optional<Item> mat=DragoonRepairRules.materialFor(st); Item item=mat.orElse(null); String id=item==null?"":BuiltInRegistries.ITEM.getKey(item).toString(); String name=item==null?"-":item.getName(ItemStack.EMPTY).getString(); int req=DragoonRepairRules.isSupportedDamagedItem(st)?DragoonRepairRules.requiredUnitsToFull(st):0; boolean has=item!=null&&DragoonRepairTransactionService.count(d,item)>=selectedUnits; ModNetwork.sendTo(viewer,new DragoonRepairPayloads.S2C_State(viewer.containerMenu.containerId,sessionId,d.getName().getString(),t.getName().getString(),viewer.getUUID().equals(dragoon),feeTrace,CurrencyService.getBalanceTrace(t),CurrencyService.getCapacity(d),selectedUnits,req,id,name,item==null?0:selectedUnits,has,targetReady,finalizing,msg==null?"":msg)); }
        private void markEnded(){ ended=true; sessions.remove(dragoon,this); sessions.remove(target,this); } private MinecraftServer server(){ return ServerLifecycleHooks.getCurrentServer(); }
    }
}
